select o.id orderId, o.number orderNumber, o.status orderStatus, o.user_id orderUserId, o.address_book_id addressBookId, o.order_time orderTime, o.checkout_time checkoutTime, o.pay_method payMethod, o.pay_status payStatus, o.amount, o.remark, o.user_name userName, o.phone, a.detail address, o.consignee, o.cancel_reason cancelReason, o.rejection_reason rejectionReason, o.cancel_time cancelTime, o.estimated_delivery_time estimatedDeliveryTime, o.delivery_status deliveryStatus, o.delivery_time deliveryTime, o.pack_amount packAmount, o.tableware_number tablewareNumber, o.tableware_status tablewareStatus from orders o left outer join address_book a on a.id = o.address_book_id
and o.status = #{status}
and o.number = #{number}
and o.phone = #{phone}
and o.user_id = #{userId}
and o.order_time between#{beginTime} and #{endTime}
order by o.order_time desc

select sum(amount) from orders


        and order_time > #{begin}


        and order_time < #{end}


        and status = #{status}
